// 3D model of the left lateral neck from Z-Anatomy meshes (CC BY-SA 4.0,
// based on BodyParts3D), plus three paths drawn for this app (phrenic nerve,
// great auricular nerve, thoracic duct). Geometry lives in
// data/lateral-neck-meshes.js, generated by tools/export_zanatomy.py.
// Coordinates are centimetres centred near the left carotid bifurcation:
// +y = superior, +z = anterior, and the patient's left side is +x.

window.ANATOMY = window.ANATOMY || { regions: {} };
window.ANATOMY.models = window.ANATOMY.models || {};

// One colour per neck level, shared with the levels diagram (js/figures.js).
window.ANATOMY.LEVEL_COLORS = {
  nodes_ia: 0xd4e36f,
  nodes_ib: 0xa9c43c,
  nodes_iia: 0x3fb6a8,
  nodes_iib: 0x2b8f86,
  nodes_iii: 0x4f8fdc,
  nodes_iv: 0x8a6ad6,
  nodes_va: 0xe3913a,
  nodes_vb: 0xc8722a,
  nodes_vi: 0xe06a9a
};

window.ANATOMY.models.lateral_neck = {
  // Default view: the left side of the neck, slightly from the front.
  camera: { target: [1.0, 0.0, 0.5], radius: 34, theta: 1.3, phi: 1.68 },

  // [theta, phi] for the view buttons. The left side faces +x.
  views: {
    lateral: [Math.PI / 2, Math.PI / 2],
    inferior: [0.8, 2.6],
    anterior: [0.05, 1.6]
  },

  look: (() => {
    const look = {
      mandible: { kind: "bone" },
      hyoid: { kind: "bone" },
      larynx: { kind: "bone", color: 0xd9d6c4 },
      clavicle: { kind: "bone" },
      sternum: { kind: "bone" },
      first_rib: { kind: "bone" },
      vertebrae: { kind: "bone" },
      temporal: { kind: "bone" },
      // Semi-transparent so the jugular chain shows through.
      scm: { kind: "muscle", color: 0xa4423f, opacity: 0.45 },
      omohyoid: { kind: "muscle", color: 0xb04a44 },
      strap: { kind: "muscle", color: 0x9e3f3f },
      digastric: { kind: "muscle" },
      stylohyoid: { kind: "muscle", color: 0x9c3a3c },
      mylohyoid: { kind: "muscle", color: 0xa8443f },
      scalenus_anterior: { kind: "muscle", color: 0x983b3c },
      scalenes: { kind: "muscle", color: 0x8f3739 },
      levator_scapulae: { kind: "muscle", color: 0x94393b },
      splenius: { kind: "muscle", color: 0x8c3638 },
      trapezius: { kind: "muscle", color: 0xa1403e },
      platysma: { kind: "muscle", color: 0xc2685a, opacity: 0.35 },
      smg: { kind: "gland", color: 0xd8a06a },
      parotid: { kind: "gland", color: 0xd9a46e },
      thyroid: { kind: "gland", color: 0xb5654f },
      cca: { kind: "artery" },
      ica: { kind: "artery" },
      eca: { kind: "artery" },
      facial_artery: { kind: "artery" },
      occipital_artery: { kind: "artery" },
      thyrocervical: { kind: "artery" },
      subclavian_artery: { kind: "artery" },
      vertebral_artery: { kind: "artery" },
      ijv: { kind: "vein" },
      ejv: { kind: "vein" },
      ajv: { kind: "vein" },
      facial_vein: { kind: "vein" },
      subclavian_vein: { kind: "vein" },
      vagus: { kind: "nerve" },
      accessory: { kind: "nerve" },
      hypoglossal: { kind: "nerve" },
      sympathetic: { kind: "nerve", color: 0xe6c86a },
      brachial_plexus: { kind: "nerve" },
      mmn: { kind: "nerve" },
      phrenic: { kind: "nerve" },
      great_auricular: { kind: "nerve" },
      thoracic_duct: { kind: "duct", color: 0xf4f0e0 }
    };
    for (const [id, color] of Object.entries(window.ANATOMY.LEVEL_COLORS)) look[id] = { kind: "node", color };
    return look;
  })(),

  build(THREE, h) {
    return h.fromMeshes("lateral_neck", this.look);
  }
};
